import net.officefloor.hq.app.period.Period;
import net.officefloor.hq.app.period.Periods;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.rate.Rates;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.hq.app.voidreason.VoidReasons;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import net.officefloor.server.http.ServerHttpConnection;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

public class ApplyClaimStatus {
    // Stored only if the claim still has the status it was loaded with, so two users cannot both move it.
    // A PENDING claim moves only by a steward's decision: "approve" (to SETTLED) or "reject" (to OPEN, with a reason);
    // a decision is refused for any claim not PENDING. A PENDING claim can also be voided, like an OPEN one.
    public void apply(@PathVariable("status") String status, @RequestBody(required = false) ClaimStatusRequest body,
            @Val Claim claim, Claims claims, People people, Rates rates, Settings settings, Sheets sheets,
            Periods periods, Rollup rollup, VoidReasons voidReasons, SettleBatches batches, ServerHttpConnection connection, Out<ClaimResponse> responseOut,
            Out<ClaimStatusRequest> requestOut) throws ClaimStatusRefusedException, ClaimProofNeededException, ClaimNoteNeededException,
            ClaimVoidReasonNeededException {
        ClaimStatus next;
        try {
            next = ClaimStatus.valueOf(status.trim().toUpperCase());
        } catch (IllegalArgumentException e) {
            throw new ClaimStatusRefusedException("Not a claim status: " + status);
        }
        String user = Audit.user(connection).trim();
        String action = body == null || body.action() == null ? "" : body.action().trim();
        String reason = body == null || body.reason() == null ? "" : body.reason().trim();
        String voidReason = body == null || body.voidReason() == null ? "" : body.voidReason().trim();
        boolean decision = !action.isEmpty();
        if (decision && !(action.equals("approve") && next == ClaimStatus.SETTLED)
                && !(action.equals("reject") && next == ClaimStatus.OPEN)) {
            throw new ClaimStatusRefusedException("Not a decision on a pending claim: " + action);
        }
        if (decision && claim.status() != ClaimStatus.PENDING) {
            throw new ClaimStatusRefusedException("Only a PENDING claim is approved or rejected.");
        }
        if (!decision && claim.status() == ClaimStatus.PENDING && next != ClaimStatus.VOID) {
            throw new ClaimStatusRefusedException("A PENDING claim is approved or rejected by a steward, or voided.");
        }
        boolean steward = Settings.STEWARD.equals(settings.role(claim.sheetId(), user));
        // Opening, settling and voiding are for the roles the sheet's permission matrix allows (approving and
        // rejecting stay with stewards, below).
        String permitted = decision ? null : switch (next) {
            case OPEN -> "open";
            case SETTLED -> "settle";
            case VOID -> "void";
            default -> null;
        };
        if (permitted != null && !settings.permits(claim.sheetId(), permitted, user)) {
            throw new ClaimStatusRefusedException("Your role is not allowed to " + permitted + " a claim.");
        }
        if (next == ClaimStatus.PENDING) {
            throw new ClaimStatusRefusedException("A claim becomes PENDING only when a clerk settles it above the clerk limit.");
        }
        // Four eyes: the user who opened a claim cannot settle it, nor approve it.
        if (next == ClaimStatus.SETTLED && claim.openedBy() != null && claim.openedBy().equals(user)) {
            throw new ClaimStatusRefusedException(claim.status() == ClaimStatus.PENDING
                    ? "The user who opened a claim cannot approve it."
                    : "The user who opened a claim cannot settle it.");
        }
        // Nor can the user who last edited it.
        if (next == ClaimStatus.SETTLED && user.equals(claims.editedBy(claim))) {
            throw new ClaimStatusRefusedException(claim.status() == ClaimStatus.PENDING
                    ? "The user who last edited a claim cannot approve it."
                    : "The user who last edited a claim cannot settle it.");
        }
        // A deferred claim cannot be settled until the sheet's today reaches its deferred-until date.
        if (next == ClaimStatus.SETTLED && claim.deferredOn(sheets.today(claim.sheetId()))) {
            throw new ClaimStatusRefusedException("The claim is deferred until " + claim.deferredUntil() + ": it cannot be settled yet.");
        }
        if (!claim.status().allows(next)) {
            throw new ClaimStatusRefusedException("A " + claim.status() + " claim cannot become " + next + ".");
        }
        // A DELETED claim is restored to DRAFT only on the sheet's today it was deleted.
        if (claim.status() == ClaimStatus.DELETED && next == ClaimStatus.DRAFT) {
            LocalDate deletedOn = claims.deletedOn(claim);
            if (deletedOn == null || !deletedOn.equals(sheets.today(claim.sheetId()))) {
                throw new ClaimStatusRefusedException("A DELETED claim can be restored only on the day it was deleted.");
            }
        }
        // A SETTLED claim is voided only by a steward, and only within a week of its settlement (the status log's
        // SETTLED date) by the sheet's today.
        if (claim.status() == ClaimStatus.SETTLED && next == ClaimStatus.VOID) {
            if (!steward) {
                throw new ClaimStatusRefusedException("Only a steward can void a SETTLED claim.");
            }
            LocalDate settledOn = claims.settledOn(claim);
            if (settledOn == null || sheets.today(claim.sheetId())
                    .isAfter(settledOn.plusDays(ClaimStatus.VOID_SETTLED_DAYS))) {
                throw new ClaimStatusRefusedException("A SETTLED claim can be voided only within "
                        + ClaimStatus.VOID_SETTLED_DAYS + " days of its settlement.");
            }
        }
        if (claim.status() == ClaimStatus.PENDING && (next == ClaimStatus.SETTLED || next == ClaimStatus.OPEN)
                && !steward) {
            throw new ClaimStatusRefusedException("Only a steward can approve or reject a pending claim.");
        }
        if (claim.status() == ClaimStatus.PENDING && next == ClaimStatus.OPEN && reason.isEmpty()) {
            throw new ClaimStatusRefusedException("Give a reason to reject the claim.");
        }
        // While the sheet has void reasons, a claim is voided only with one of them; with none, no reason is kept.
        if (next == ClaimStatus.VOID) {
            List<String> reasons = voidReasons.list(claim.sheetId());
            if (reasons.isEmpty()) {
                voidReason = "";
            } else if (!reasons.contains(voidReason)) {
                throw new ClaimVoidReasonNeededException(voidReason.isEmpty()
                        ? "Choose a void reason to void the claim."
                        : "\"" + voidReason + "\" is not one of the sheet's void reasons.");
            }
        }
        // Settling (or approving) freezes the late charge on the sheet's today into the due.
        BigDecimal due = settings.withLate(claim, due(claim, people, rates, settings), sheets.today(claim.sheetId()));
        // A claim whose due is above the proof threshold in force on its date (its person's grade's, else the sheet's) is settled or approved only once it has a
        // proof, whoever settles it, and before the clerk limit is considered (a due of n/a is within any threshold).
        if (next == ClaimStatus.SETTLED && claim.proofs() == 0 && due != null) {
            BigDecimal threshold = settings.proofThreshold(claim);
            if (threshold != null && due.compareTo(threshold) > 0) {
                throw new ClaimProofNeededException("The claim's due is above the proof threshold (" + threshold.toPlainString()
                        + "): add a proof before it is " + (claim.status() == ClaimStatus.PENDING ? "approved." : "settled."));
            }
        }
        // A claim whose due is above the note threshold in force on its date is opened only once it has a note (a due
        // of n/a is within any threshold).
        if (next == ClaimStatus.OPEN && claim.status() == ClaimStatus.DRAFT && due != null
                && (claim.note() == null || claim.note().isBlank())) {
            BigDecimal threshold = settings.noteThreshold(claim.sheetId(), claim.date());
            if (threshold != null && due.compareTo(threshold) > 0) {
                throw new ClaimNoteNeededException("The claim's due is above the note threshold (" + threshold.toPlainString()
                        + "): give it a note before it is opened.");
            }
        }
        // A clerk settles only a claim whose due is at or below the clerk limit (a due of n/a is within any
        // limit); above it the claim goes PENDING, for a steward to approve. A steward settles anything.
        if (next == ClaimStatus.SETTLED && claim.status() == ClaimStatus.OPEN && due != null && !steward) {
            BigDecimal limit = settings.clerkLimit(claim.sheetId());
            if (limit != null && due.compareTo(limit) > 0) {
                next = ClaimStatus.PENDING;
            }
        }
        // A DRAFT claim belonging to a period that caps its claims (its due-by falls in it) is opened only while its
        // person has fewer OPEN or PENDING claims in the period than the cap.
        if (next == ClaimStatus.OPEN && claim.status() == ClaimStatus.DRAFT) {
            Period capped = periods.on(claim.sheetId(), claim.dueBy());
            if (capped != null && capped.cap() != null
                    && claims.openInPeriod(claim.sheetId(), claim.personId(), capped) >= capped.cap()) {
                throw new ClaimStatusRefusedException("The person already has " + capped.cap()
                        + " open or pending claims in the period " + capped.name() + ", its cap.");
            }
        }
        // While the sheet numbers by period (its today on or after the from-date), an opened claim is numbered
        // within the period its due-by falls in, or in the no-period sequence; otherwise sheet-wide.
        String scope = null;
        LocalDate numberingFrom = settings.periodNumberingFrom(claim.sheetId());
        if (next == ClaimStatus.OPEN && numberingFrom != null && !sheets.today(claim.sheetId()).isBefore(numberingFrom)) {
            Period period = periods.on(claim.sheetId(), claim.dueBy());
            scope = period == null ? "" : period.name();
        }
        Claim changed = claims.changeStatus(claim, next, due, user, scope);
        if (changed == null) {
            throw new ClaimStatusRefusedException("A " + claim.status() + " claim cannot become " + next + ".");
        }
        // Settled one at a time, the claim leaves any batch that settled it before (a bulk settle records its batch after).
        if (!decision && (next == ClaimStatus.SETTLED || next == ClaimStatus.PENDING)) {
            batches.remove(changed.id());
        }
        if (next == ClaimStatus.VOID && !voidReason.isEmpty()) {
            voidReasons.voided(changed.id(), voidReason);
        }
        claims.log(changed, user, sheets.today(claim.sheetId()), rollup.figure(changed));
        responseOut.set(ClaimResponse.from(changed));
        requestOut.set(new ClaimStatusRequest(action, reason, voidReason));
    }

    /**
     * The claim's due now, before its late charge: the figure its person's last statement bound it to (a PENDING
     * claim is not bound: its figure is live), otherwise its amount times its
     * person's grade's rate on the claim's date, rounded by the policy date (not yet floored); null when none applies.
     */
    private static BigDecimal due(Claim claim, People people, Rates rates, Settings settings) {
        if (claim.stated() && claim.status() != ClaimStatus.PENDING) {
            return claim.statedDue();
        }
        Person person = people.find(claim.sheetId(), claim.personId());
        if (person == null) {
            return null;
        }
        BigDecimal rate = rates.on(claim.sheetId(), person.gradeOn(claim.date()), claim.date());
        return settings.live(claim, rate);
    }
}
package net.officefloor.hq.app.claim;

/**
 * Where a claim is in its life: DRAFT, then OPEN, then SETTLED; a DRAFT, OPEN or PENDING claim can be VOID, and a
 * SETTLED one too, by a steward within {@link #VOID_SETTLED_DAYS} days of its settlement. A clerk's
 * settle of a claim whose due is above the clerk limit makes it PENDING instead, until a steward approves it (SETTLED)
 * or rejects it (back to OPEN). A DRAFT claim can be DELETED, counting nowhere, and restored to DRAFT on the same
 * sheet's today it was deleted.
 */
public enum ClaimStatus {
    DRAFT, OPEN, PENDING, SETTLED, VOID, DELETED;

    /** How many days after its settlement (by the sheet's today) a steward may still void a SETTLED claim. */
    public static final int VOID_SETTLED_DAYS = 7;

    /** Whether a claim in this status may move to {@code next}. */
    public boolean allows(ClaimStatus next) {
        return switch (next) {
            case OPEN -> this == DRAFT || this == PENDING;
            case PENDING -> this == OPEN;
            case SETTLED -> this == OPEN || this == PENDING;
            case VOID -> this == DRAFT || this == OPEN || this == PENDING || this == SETTLED;
            case DRAFT -> this == DELETED;
            case DELETED -> this == DRAFT;
        };
    }

    /** Whether a claim in this status is open: OPEN, or PENDING, which is handled like OPEN in every total. */
    public boolean isOpen() {
        return this == OPEN || this == PENDING;
    }

    /** Whether a claim in this status counts toward the totals: an open or a SETTLED one. */
    public boolean counts() {
        return isOpen() || this == SETTLED;
    }

    /** The audit event of a change from {@code from} to this status. */
    public String event(ClaimStatus from) {
        if (from == DELETED && this == DRAFT) {
            return "CLAIM_RESTORED";
        }
        if (from == PENDING) {
            return this == SETTLED ? "CLAIM_APPROVED" : this == OPEN ? "CLAIM_REJECTED" : event();
        }
        return event();
    }

    /** The audit event of a change to this status. */
    public String event() {
        return switch (this) {
            case OPEN -> "CLAIM_OPENED";
            case PENDING -> "CLAIM_PENDING";
            case SETTLED -> "CLAIM_SETTLED";
            case VOID -> "CLAIM_VOIDED";
            case DRAFT -> "CLAIM_DRAFTED";
            case DELETED -> "CLAIM_DELETED";
        };
    }
}
package net.officefloor.hq.app.claim;

import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.springframework.dao.DuplicateKeyException;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/** The claims whose editor a user has open, kept per sheet. A user holds at most one lock on a sheet. */
@Repository
public class ClaimLocks {

    private final JdbcTemplate jdbc;

    public ClaimLocks(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** The user holding the claim's lock; null when it is not locked. */
    public String lockedBy(Claim claim) {
        List<String> by = jdbc.query("SELECT locked_by FROM claim_lock WHERE claim_id = ?",
                (rs, n) -> rs.getString("locked_by"), claim.id());
        return by.isEmpty() ? null : by.get(0);
    }

    /** The sheet's locks: the user holding each, by claim id. */
    public Map<Long, String> list(String sheetId) {
        Map<Long, String> locks = new HashMap<>();
        jdbc.query("SELECT * FROM claim_lock WHERE sheet_id = ?",
                rs -> {
                    locks.put(rs.getLong("claim_id"), rs.getString("locked_by"));
                }, sheetId);
        return locks;
    }

    /**
     * Locks the claim for {@code user}, releasing any other lock they hold on the sheet, and returns true; false when
     * another user holds it.
     */
    public boolean lock(Claim claim, String user) {
        jdbc.update("DELETE FROM claim_lock WHERE sheet_id = ? AND locked_by = ? AND claim_id <> ?", claim.sheetId(),
                user, claim.id());
        try {
            jdbc.update("INSERT INTO claim_lock (claim_id, sheet_id, locked_by) VALUES (?, ?, ?)", claim.id(),
                    claim.sheetId(), user);
            return true;
        } catch (DuplicateKeyException e) {
            return user.equals(lockedBy(claim));
        }
    }

    /** Releases the claim's lock if {@code user} holds it. */
    public void release(Claim claim, String user) {
        jdbc.update("DELETE FROM claim_lock WHERE claim_id = ? AND locked_by = ?", claim.id(), user);
    }

    /** Releases every lock on the sheet. */
    public void releaseAll(String sheetId) {
        jdbc.update("DELETE FROM claim_lock WHERE sheet_id = ?", sheetId);
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.format.DateTimeFormatter;
import java.time.format.DateTimeParseException;
import java.time.format.ResolverStyle;
import java.util.Arrays;
import java.util.List;
import java.util.Locale;
import java.util.regex.Pattern;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidateClaim {

    private static final Pattern AMOUNT = Pattern.compile("-?\\d+(\\.\\d{1,2})?");

    private static final Pattern NUMBER = Pattern.compile("\\d{1,18}|.{1,280}-\\d{1,18}");

    private static final DateTimeFormatter ISO = DateTimeFormatter.ofPattern("uuuu-MM-dd")
            .withResolverStyle(ResolverStyle.STRICT);

    // The amount is required; a blank date takes the sheet's today (filled in when stored); the note may be empty.
    // A negative amount is a correction and must name the number it corrects; no other claim may name one.
    // Whether that number is a SETTLED claim of the same person is checked once the person is loaded.
    // The external reference is kept without surrounding spaces; whether the sheet already uses it is checked once loaded.
    public void validate(@RequestBody ClaimRequest body, Out<ClaimInput> input) throws InvalidClaimException {
        input.set(parse(body));
    }

    /** The claim form's rules on a typed body; shared with the paste box, which checks every line by them. */
    static ClaimInput parse(ClaimRequest body) throws InvalidClaimException {
        String amount = body == null || body.amount() == null ? "" : body.amount().trim();
        String date = body == null || body.date() == null ? "" : body.date().trim();
        String note = body == null || body.note() == null ? "" : body.note().trim();
        String corrects = body == null || body.corrects() == null ? "" : body.corrects().trim();
        String ref = body == null || body.ref() == null ? "" : body.ref().trim();
        if (!AMOUNT.matcher(amount).matches()) {
            throw new InvalidClaimException("The amount must be a number with up to two decimals.");
        }
        BigDecimal value = new BigDecimal(amount).setScale(2);
        if (value.signum() < 0 && corrects.isEmpty()) {
            throw new InvalidClaimException("A negative amount is a correction: name the number of the settled claim it corrects.");
        }
        if (value.signum() >= 0 && !corrects.isEmpty()) {
            throw new InvalidClaimException("Only a claim with a negative amount corrects another.");
        }
        if (!corrects.isEmpty() && !NUMBER.matcher(corrects).matches()) {
            throw new InvalidClaimException("Not a claim number: " + corrects);
        }
        LocalDate parsed = null;
        if (!date.isEmpty()) {
            try {
                parsed = LocalDate.parse(date, ISO);
            } catch (DateTimeParseException e) {
                throw new InvalidClaimException("Not a date (yyyy-mm-dd): " + date);
            }
        }
        return new ClaimInput(value, parsed, note, corrects.isEmpty() ? null : corrects,
                ref.isEmpty() ? null : ref, tags(body == null ? null : body.tags()));
    }

    /** Comma separated tags as a claim keeps them: each trimmed and lower-cased, blanks and repeats dropped, sorted. */
    static List<String> tags(String typed) {
        if (typed == null) {
            return List.of();
        }
        return Arrays.stream(typed.split(",")).map(t -> t.trim().toLowerCase(Locale.ROOT)).filter(t -> !t.isEmpty())
                .distinct().sorted().toList();
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import net.officefloor.hq.app.period.Periods;
import net.officefloor.hq.app.person.Person;

/** The claim form's rules on a typed body, for a feature outside claims that must take only what the form takes. */
public final class ClaimFormRules {

    private ClaimFormRules() {
    }

    public static ClaimInput parse(ClaimRequest body) throws InvalidClaimException {
        return ValidateClaim.parse(body);
    }

    /** Refuses a new claim due by {@code dueBy} when that falls inside a closed period, as the claim form does. */
    public static void refuseClosed(Periods periods, String sheet, LocalDate dueBy) throws ClaimInClosedPeriodException {
        RefuseClosedNewInput.check(periods, sheet, dueBy);
    }

    /** Refuses a claim dated {@code date} for a person retired on it, as the claim form does. */
    public static void refuseRetired(Person person, LocalDate date) throws ClaimAfterRetirementException {
        RefuseRetiredInput.check(person, date);
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import net.officefloor.hq.app.holiday.Holidays;
import net.officefloor.hq.app.period.Period;
import net.officefloor.hq.app.period.Periods;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

public class RefuseClosedNewInput {
    // A claim belongs to the period its due-by falls in: the due-by the claim being added would be fixed with (its date
    // — a blank date is the entry date, else the sheet's today — plus its person's terms, moved past the sheet's holidays) must not be in a closed period.
    public void refuse(@PathVariable("sheetId") String sheetId, @Val ClaimInput input, @Val Person person,
            Settings settings, Holidays holidays, Periods periods) throws ClaimInClosedPeriodException {
        String sheet = sheetId.trim();
        LocalDate date = input.date() != null ? input.date() : settings.entryDate(sheet);
        check(periods, sheet, holidays.dueBy(sheet, date, person.termsOn(date, settings)));
    }

    /** Refuses a new claim due by {@code dueBy} when that falls inside a closed period. */
    static void check(Periods periods, String sheet, LocalDate dueBy) throws ClaimInClosedPeriodException {
        Period closed = periods.closedOn(sheet, dueBy);
        if (closed != null) {
            throw new ClaimInClosedPeriodException("The period " + closed.name() + " is closed: no claim due by "
                    + dueBy + " can be added.");
        }
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.Retirement;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.plugin.variable.Val;

public class RefuseRetiredInput {
    // The date a claim is being added to (a blank date is the entry date, else the sheet's today) must not be after its person's retirement,
    // nor strictly between the dates of one of their past retirements.
    public void refuse(@Val ClaimInput input, @Val Person person, Settings settings) throws ClaimAfterRetirementException {
        check(person, input.date() != null ? input.date() : settings.entryDate(person.sheetId()));
    }

    static void check(Person person, LocalDate date) throws ClaimAfterRetirementException {
        if (person != null && person.retired() && date.isAfter(person.retiredFrom())) {
            throw new ClaimAfterRetirementException(person.name() + " is retired from " + person.retiredFrom()
                    + ": no claim dated " + date + " can be added or edited.");
        }
        if (person != null) {
            for (Retirement past : person.retirements()) {
                if (past.excludes(date)) {
                    throw new ClaimAfterRetirementException(person.name() + " was retired from " + past.from() + " to "
                            + past.to() + ": no claim dated " + date + " can be added or edited.");
                }
            }
        }
    }
}

